/* From Uiverse.io by EmmaxPlay - Tags: card */
.__UIV_SCOPE__ .card {
 width: 190px;
 height: 254px;
 margin: 0 auto;
 background-color: #011522;
 border-radius: 8px;
 z-index: 1;
}

.__UIV_SCOPE__ .tools {
 display: flex;
 align-items: center;
 padding: 9px;
}

.__UIV_SCOPE__ .circle {
 padding: 0 4px;
}

.__UIV_SCOPE__ .box {
 display: inline-block;
 align-items: center;
 width: 10px;
 height: 10px;
 padding: 1px;
 border-radius: 50%;
}

.__UIV_SCOPE__ .red {
 background-color: #ff605c;
}

.__UIV_SCOPE__ .yellow {
 background-color: #ffbd44;
}

.__UIV_SCOPE__ .green {
 background-color: #00ca4e;
}
